declare const React: any;
declare const MODI: any;
declare const useButton: any;

const { useState, useEffect, useRef } = React;

const RAW_LANES = [
  { id: 'button', label: 'BUTTON', glyph: '●', color: '#38bdf8', rgb: [56, 189, 248] },
  { id: 'left', label: 'LEFT', glyph: '←', color: '#f87171', rgb: [248, 113, 113] },
  { id: 'down', label: 'DOWN', glyph: '↓', color: '#fbbf24', rgb: [251, 191, 36] },
  { id: 'up', label: 'UP', glyph: '↑', color: '#34d399', rgb: [52, 211, 153] },
  { id: 'right', label: 'RIGHT', glyph: '→', color: '#60a5fa', rgb: [96, 165, 250] },
  { id: 'dial', label: 'DIAL', glyph: '↻', color: '#c084fc', rgb: [192, 132, 252] },
];

const LANES = RAW_LANES.map((lane, index) => ({
  ...lane,
  x: ((index + 0.5) / RAW_LANES.length) * 100,
}));
const LANE_BY_ID = LANES.reduce((acc, lane) => ({ ...acc, [lane.id]: lane }), {});

const START_Y = 8;
const TARGET_Y = 74;
const INTRO_TRAVEL_MS = 3600;
const EXCELLENT_MS = 45;
const GREAT_MS = 90;
const NICE_MS = 145;
const MISS_MS = 190;
const JOY_DEADZONE = 42;

const SEQUENCE = [
  'button', 'left', 'up', 'dial', 'right', 'down',
  'button', 'right', 'up', 'left', 'dial', 'down',
  'left', 'button', 'up', 'right', 'dial', 'down',
  'button', 'left', 'right', 'up', 'dial', 'down',
];
const CHORD_SEQUENCE = [
  ['button', 'up'],
  ['dial', 'left'],
  ['button', 'right'],
  ['dial', 'down'],
  ['button', 'dial'],
  ['dial', 'up'],
];
const DIFFICULTY_STEPS = [
  { at: 0, travelMs: INTRO_TRAVEL_MS, gaps: [1650, 1550, 1750, 1500, 1850, 1600], chordEvery: 0 },
  { at: 18000, travelMs: 3100, gaps: [1320, 1240, 1400, 1180, 1500, 1280], chordEvery: 0 },
  { at: 40000, travelMs: 2650, gaps: [1040, 960, 1120, 900, 1200, 980], chordEvery: 7 },
  { at: 70000, travelMs: 2300, gaps: [840, 780, 920, 740, 980, 800], chordEvery: 5 },
  { at: 105000, travelMs: 2050, gaps: [700, 640, 760, 610, 820, 680], chordEvery: 4 },
];

const GRADE = {
  excellent: { text: 'EXCELLENT', score: 320, rgb: [255, 202, 40], color: '#facc15', tone: 1320 },
  great: { text: 'GREAT', score: 180, rgb: [34, 211, 238], color: '#22d3ee', tone: 1040 },
  nice: { text: 'NICE', score: 80, rgb: [52, 211, 153], color: '#34d399', tone: 820 },
  oops: { text: 'OOPS', score: 0, rgb: [248, 113, 113], color: '#f87171', tone: 220 },
};

const KEY_TO_LANE = {
  ' ': 'button',
  Enter: 'button',
  b: 'button',
  B: 'button',
  ArrowLeft: 'left',
  a: 'left',
  A: 'left',
  ArrowDown: 'down',
  s: 'down',
  S: 'down',
  ArrowUp: 'up',
  w: 'up',
  W: 'up',
  ArrowRight: 'right',
  d: 'right',
  D: 'right',
  q: 'dial',
  Q: 'dial',
  e: 'dial',
  E: 'dial',
};

function safeModi(run) {
  try {
    if (typeof MODI !== 'undefined') run();
  } catch (error) {
    // Preview can run without connected hardware.
  }
}

function subscribeModi(moduleKey, valueKey, onValue, pollMs) {
  let off = () => {};
  safeModi(() => {
    const maybeOff = MODI.onValue(moduleKey, 1, valueKey, onValue, { pollMs });
    if (typeof maybeOff === 'function') off = maybeOff;
  });
  return off;
}

function getNoteY(note, gameTime) {
  const travelMs = note.travelMs || INTRO_TRAVEL_MS;
  const startedAt = note.judgeAt - travelMs;
  const progress = Math.max(0, Math.min(1, (gameTime - startedAt) / travelMs));
  return START_Y + (TARGET_Y - START_Y) * progress;
}

function difficultyAt(gameTime) {
  let difficulty = DIFFICULTY_STEPS[0];
  for (const step of DIFFICULTY_STEPS) {
    if (gameTime >= step.at) difficulty = step;
  }
  return difficulty;
}

function lanesForChartStep(chartIndex, difficulty) {
  if (difficulty.chordEvery && chartIndex > 10 && chartIndex % difficulty.chordEvery === difficulty.chordEvery - 1) {
    return CHORD_SEQUENCE[Math.floor(chartIndex / difficulty.chordEvery) % CHORD_SEQUENCE.length];
  }
  return [SEQUENCE[chartIndex % SEQUENCE.length]];
}

function gradeFromDelta(delta) {
  if (delta <= EXCELLENT_MS) return 'excellent';
  if (delta <= GREAT_MS) return 'great';
  if (delta <= NICE_MS) return 'nice';
  return null;
}

function joystickDirection(x, y) {
  const ax = Math.abs(x);
  const ay = Math.abs(y);
  if (ax < JOY_DEADZONE && ay < JOY_DEADZONE) return null;
  if (ax >= ay) return x > 0 ? 'right' : 'left';
  return y > 0 ? 'up' : 'down';
}

function dialDelta(current, previous) {
  if (previous === null || previous === undefined) return 0;
  const range = Math.max(Math.abs(current), Math.abs(previous)) > 120 ? 360 : 100;
  let delta = current - previous;
  if (delta > range / 2) delta -= range;
  if (delta < -range / 2) delta += range;
  return delta;
}

