          {hud.score.toString().padStart(7, '0')}
        </div>
      </div>
      <div className="flex items-start gap-8 text-right">
        <div>
          <div className="text-xs font-black tracking-widest text-cyan-200/70">COMBO</div>
          <div className="text-4xl font-black tabular-nums" style={{ color: hud.combo > 0 ? '#f472b6' : '#64748b' }}>
            {hud.combo}
          </div>
        </div>
        <div>
          <div className="text-xs font-black tracking-widest text-cyan-200/70">MAX</div>
          <div className="text-3xl font-black tabular-nums text-cyan-200">{hud.maxCombo}</div>
        </div>
      </div>
      <div className="absolute left-0 right-0 top-16 h-3 overflow-hidden rounded-full border border-white/15 bg-black/50">
        <div
          className="h-full transition-all duration-150"
          style={{
            width: `${hud.hp}%`,
            background: hud.hp > 45
              ? 'linear-gradient(90deg,#10b981,#84cc16)'
              : hud.hp > 20
                ? 'linear-gradient(90deg,#f97316,#facc15)'
                : 'linear-gradient(90deg,#dc2626,#fb7185)',
          }}
        />
      </div>
    </div>
