}

function TargetPad({ lane, active, onInput }) {
  return (
    <button
      type="button"
      aria-label={lane.label}
      onPointerDown={(event) => {
        event.preventDefault();
        onInput(lane.id);
      }}
      className="absolute z-20 flex -translate-x-1/2 -translate-y-1/2 flex-col items-center justify-center rounded-xl border-2 bg-black/70 font-black shadow-xl transition-transform active:scale-95"
      style={{
        left: `${lane.x}%`,
        top: `${TARGET_Y}%`,
        width: 'clamp(50px, 8vw, 78px)',
        height: 'clamp(58px, 8.5vw, 84px)',
        borderColor: active ? '#ffffff' : lane.color,
        color: active ? '#ffffff' : lane.color,
        boxShadow: active
          ? `0 0 34px ${lane.color}, inset 0 0 22px ${lane.color}66`
          : `0 0 14px ${lane.color}55, inset 0 0 18px rgba(255,255,255,0.04)`,
        background: active ? `linear-gradient(180deg, ${lane.color}cc, rgba(8,13,25,0.95))` : 'rgba(3,7,18,0.82)',
      }}
    >
      <span style={{ fontSize: 'clamp(26px, 4vw, 42px)', lineHeight: 1 }}>{lane.glyph}</span>
      <span className="mt-1 text-[10px] tracking-widest">{lane.label}</span>
    </button>
  );
}

function FallingNote({ note, gameTime }) {
  const lane = LANE_BY_ID[note.lane];
  const y = getNoteY(note, gameTime);
  const nearTarget = Math.abs(y - TARGET_Y) < 5;
  return (
    <div
      className="absolute z-10 flex -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-xl border-2 font-black"
      style={{
        left: `${lane.x}%`,
        top: `${y}%`,
        width: 'clamp(46px, 7.4vw, 70px)',
        height: 'clamp(46px, 7.4vw, 70px)',
        color: '#ffffff',
        borderColor: lane.color,
        background: `radial-gradient(circle at 35% 25%, rgba(255,255,255,0.92), ${lane.color} 38%, rgba(5,10,25,0.95) 100%)`,
        boxShadow: nearTarget
          ? `0 0 44px ${lane.color}, 0 0 16px #ffffff`
          : `0 0 24px ${lane.color}99`,
        fontSize: 'clamp(24px, 4vw, 40px)',
      }}
    >
      {lane.glyph}
    </div>
  );
}

function JudgmentBurst({ judgment }) {
  if (!judgment) return null;
  const grade = GRADE[judgment.grade] || GRADE.oops;
  return (
    <div className="pointer-events-none absolute inset-0 z-40 flex items-center justify-center">
      <div
        key={judgment.id}
        className="font-black"
        style={{
          animation: 'judgePop 520ms ease-out forwards',
          color: grade.color,
          fontSize: 'clamp(44px, 9vw, 118px)',
          textShadow: `0 0 16px ${grade.color}, 0 0 46px ${grade.color}`,
        }}
      >
        {grade.text}
      </div>
    </div>
  );
}

function HardwareStatus({ inputView }) {
  const joyDir = inputView.joyDir ? inputView.joyDir.toUpperCase() : 'CENTER';
  return (
    <div className="absolute bottom-3 left-1/2 z-30 grid w-[min(92vw,760px)] -translate-x-1/2 grid-cols-3 gap-2 text-white">
      <div className="rounded-lg border border-cyan-300/30 bg-black/70 px-3 py-2">
        <div className="text-[10px] font-black tracking-widest text-cyan-200/70">BUTTON</div>
        <div className="mt-1 text-xl font-black" style={{ color: inputView.button ? '#38bdf8' : '#94a3b8' }}>
          {inputView.button ? 'CLICK' : 'READY'}
        </div>
      </div>
      <div className="rounded-lg border border-emerald-300/30 bg-black/70 px-3 py-2">
        <div className="text-[10px] font-black tracking-widest text-emerald-200/70">JOYSTICK</div>
        <div className="mt-1 text-xl font-black text-emerald-200">{joyDir}</div>
        <div className="text-[10px] text-slate-400">X {Math.round(inputView.joyX)} / Y {Math.round(inputView.joyY)}</div>
      </div>
      <div className="rounded-lg border border-violet-300/30 bg-black/70 px-3 py-2">
        <div className="text-[10px] font-black tracking-widest text-violet-200/70">DIAL</div>
        <div className="mt-1 text-xl font-black" style={{ color: inputView.dialPulse ? '#c084fc' : '#c4b5fd' }}>
          {inputView.dialPulse ? 'TURN' : Math.round(inputView.dial)}
        </div>
      </div>
    </div>
  );
}

function ReadyOverlay({ onStart }) {
  return (
    <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/82 backdrop-blur-sm">
      <div className="text-center">
        <div className="text-7xl font-black tracking-widest text-white" style={{ textShadow: '0 0 32px rgba(34,211,238,0.65)' }}>
          MODI DDR
        </div>
        <button
          type="button"
          onClick={onStart}
          className="mt-8 rounded-xl border-2 border-cyan-200 bg-cyan-400 px-12 py-4 text-2xl font-black tracking-widest text-slate-950 shadow-2xl transition-transform hover:scale-105 active:scale-95"
          style={{ boxShadow: '0 0 34px rgba(34,211,238,0.62)' }}
        >
          START
        </button>
      </div>
    </div>
  );
}

function GameOverOverlay({ hud, onStart }) {
  return (
    <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/88 backdrop-blur-sm">
      <div className="text-center text-white">
        <div className="text-6xl font-black text-rose-300" style={{ textShadow: '0 0 24px rgba(251,113,133,0.7)' }}>
          GAME OVER
        </div>
        <div className="mt-6 text-7xl font-black tabular-nums text-amber-300">{hud.score.toString().padStart(7, '0')}</div>
        <div className="mt-3 text-xl font-black tracking-widest text-cyan-100">MAX COMBO {hud.maxCombo}</div>
        <button
          type="button"
          onClick={onStart}
          className="mt-8 rounded-xl border-2 border-amber-200 bg-amber-300 px-12 py-4 text-2xl font-black tracking-widest text-slate-950 transition-transform hover:scale-105 active:scale-95"
        >
          RESTART
        </button>
      </div>
    </div>
  );
}

function App() {
  const [phase, setPhase] = useState('ready');
  const [gameTime, setGameTime] = useState(0);
  const [notes, setNotes] = useState([]);
  const [hud, setHud] = useState({ score: 0, combo: 0, maxCombo: 0, hp: 100, excellent: 0, great: 0, nice: 0, oops: 0 });
  const [judgment, setJudgment] = useState(null);
  const [laneFlash, setLaneFlash] = useState({});
  const [inputView, setInputView] = useState({ button: false, joyX: 0, joyY: 0, joyDir: null, dial: 0, dialPulse: false });

  const phaseRef = useRef('ready');
  const startAtRef = useRef(0);
  const notesRef = useRef([] as any[]);
  const nextIdRef = useRef(1);
  const nextJudgeAtRef = useRef(INTRO_TRAVEL_MS);
  const chartIndexRef = useRef(0);
  const hudRef = useRef({ score: 0, combo: 0, maxCombo: 0, hp: 100, excellent: 0, great: 0, nice: 0, oops: 0 });
  const inputRef = useRef({
    joyX: 0,
    joyY: 0,
    joyDir: null,
    dial: 0,
    dialLast: null,
    lastInputAt: {},
    viewAt: 0,
  });

  const button = useButton(1);
  const btnClicked = button && button.clicked;

  useEffect(() => {
    phaseRef.current = phase;
  }, [phase]);

  function commitHud() {
    setHud({ ...hudRef.current });
  }

  function flashLane(laneId, duration = 150) {
    setLaneFlash((current) => ({ ...current, [laneId]: true }));
    window.setTimeout(() => {
      setLaneFlash((current) => ({ ...current, [laneId]: false }));
    }, duration);
  }

  function showJudgment(gradeName) {
    const id = performance.now();
    setJudgment({ id, grade: gradeName });
    window.setTimeout(() => {
      setJudgment((current) => (current && current.id === id ? null : current));
    }, 520);
  }

  function playFeedback(gradeName) {
    const grade = GRADE[gradeName] || GRADE.oops;
    safeModi(() => {
      MODI.led(1).setColor(...grade.rgb);
      MODI.speaker(1).playTone(grade.tone, gradeName === 'oops' ? 55 : 75);
      window.setTimeout(() => MODI.speaker(1).stop(), gradeName === 'oops' ? 150 : 105);
      window.setTimeout(() => MODI.led(1).off(), 180);
    });
  }

  function startGame() {
    notesRef.current = [];
    nextIdRef.current = 1;
    chartIndexRef.current = 0;
    nextJudgeAtRef.current = INTRO_TRAVEL_MS;
    startAtRef.current = performance.now();
    hudRef.current = { score: 0, combo: 0, maxCombo: 0, hp: 100, excellent: 0, great: 0, nice: 0, oops: 0 };
    inputRef.current.lastInputAt = {};
    phaseRef.current = 'playing';
    setPhase('playing');
    setGameTime(0);
    setNotes([]);
    setJudgment(null);
    setLaneFlash({});
    commitHud();
    safeModi(() => {
      MODI.led(1).setColor(20, 180, 255);
      window.setTimeout(() => MODI.led(1).off(), 220);
    });
  }

  function finishGame() {
    if (phaseRef.current === 'gameOver') return;
    phaseRef.current = 'gameOver';
    setPhase('gameOver');
    safeModi(() => {
      MODI.led(1).setColor(255, 35, 35);
      MODI.speaker(1).playTone(160, 70);
      window.setTimeout(() => MODI.speaker(1).stop(), 240);
    });
  }

  function registerMiss(note) {
    const lane = LANE_BY_ID[note.lane];
    hudRef.current.hp = Math.max(0, hudRef.current.hp - 12);
    hudRef.current.combo = 0;
    hudRef.current.oops += 1;
    flashLane(note.lane, 210);
    showJudgment('oops');
    playFeedback('oops');
    commitHud();
    if (lane) {
      setInputView((current) => ({ ...current, lastMiss: lane.id }));
    }
    if (hudRef.current.hp <= 0) finishGame();
  }

  function queueInput(laneId) {
    if (phaseRef.current !== 'playing') {
      if (laneId === 'button') startGame();
      return;
    }

    const realNow = performance.now();
    const lastAt = inputRef.current.lastInputAt[laneId] || -Infinity;
    if (realNow - lastAt < 90) return;
    inputRef.current.lastInputAt[laneId] = realNow;
    flashLane(laneId);

    const now = realNow - startAtRef.current;
    let best: any = null;
    let bestDelta = Infinity;
    for (const note of notesRef.current) {
      if (note.lane !== laneId) continue;
      const delta = Math.abs(now - note.judgeAt);
      if (delta < bestDelta) {
        best = note;
        bestDelta = delta;
      }
    }

    const gradeName = gradeFromDelta(bestDelta);
    if (!best || !gradeName) return;

    notesRef.current = notesRef.current.filter((note) => note.id !== best.id);
    setNotes([...notesRef.current]);

    const grade = GRADE[gradeName];
    hudRef.current.score += grade.score + hudRef.current.combo * 8;
    hudRef.current.combo += 1;
    hudRef.current.maxCombo = Math.max(hudRef.current.maxCombo, hudRef.current.combo);
    hudRef.current[gradeName] += 1;
    commitHud();
    showJudgment(gradeName);
    playFeedback(gradeName);
  }

  useEffect(() => {
    if (btnClicked) {
      setInputView((current) => ({ ...current, button: true }));
      window.setTimeout(() => setInputView((current) => ({ ...current, button: false })), 140);
      queueInput('button');
    }
  }, [btnClicked]);

  useEffect(() => {
    const updateJoy = () => {
      const nextDir = joystickDirection(inputRef.current.joyX, inputRef.current.joyY);
      if (nextDir !== inputRef.current.joyDir) {
        inputRef.current.joyDir = nextDir;
        if (nextDir) queueInput(nextDir);
      }

      const now = performance.now();
      if (now - inputRef.current.viewAt > 45) {
        inputRef.current.viewAt = now;
        setInputView((current) => ({
          ...current,
          joyX: inputRef.current.joyX,
          joyY: inputRef.current.joyY,
          joyDir: nextDir,
        }));
      }
    };

    const offX = subscribeModi('joystick', 'x', (value) => {
      inputRef.current.joyX = Number(value) || 0;
      updateJoy();
    }, 24);
    const offY = subscribeModi('joystick', 'y', (value) => {
      inputRef.current.joyY = Number(value) || 0;
      updateJoy();
    }, 24);
    return () => {
      offX();
      offY();
    };
  }, []);

  useEffect(() => {
    const offDial = subscribeModi('dial', 'turn', (value) => {
      const current = Number(value) || 0;
      const previous = inputRef.current.dialLast;
      const delta = dialDelta(current, previous);
      const range = Math.max(Math.abs(current), Math.abs(previous || 0)) > 120 ? 360 : 100;
      inputRef.current.dialLast = current;
      inputRef.current.dial = current;
      setInputView((view) => ({ ...view, dial: current }));

      if (Math.abs(delta) >= (range === 360 ? 8 : 3)) {
        setInputView((view) => ({ ...view, dial: current, dialPulse: true }));
        window.setTimeout(() => setInputView((view) => ({ ...view, dialPulse: false })), 150);
        queueInput('dial');
      }
    }, 35);
    return () => offDial();
  }, []);

  useEffect(() => {
    const onKeyDown = (event) => {
      if (event.repeat) return;
      const laneId = KEY_TO_LANE[event.key];
      if (!laneId) return;
      event.preventDefault();
      if (laneId === 'button') {
        setInputView((current) => ({ ...current, button: true }));
        window.setTimeout(() => setInputView((current) => ({ ...current, button: false })), 120);
      }
      if (laneId === 'dial') {
        setInputView((current) => ({ ...current, dialPulse: true }));
        window.setTimeout(() => setInputView((current) => ({ ...current, dialPulse: false })), 150);
      }
      queueInput(laneId);
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, []);

  useEffect(() => {
    if (phase !== 'playing') return;

    let raf = 0;
    const loop = () => {
      const now = performance.now() - startAtRef.current;
      let changed = false;

      while (true) {
        const difficulty = difficultyAt(nextJudgeAtRef.current);
        if (nextJudgeAtRef.current > now + difficulty.travelMs) break;

        const laneIds = lanesForChartStep(chartIndexRef.current, difficulty);
        for (const laneId of laneIds) {
          notesRef.current.push({
            id: nextIdRef.current++,
            lane: laneId,
            judgeAt: nextJudgeAtRef.current,
            travelMs: difficulty.travelMs,
          });
        }
        nextJudgeAtRef.current += difficulty.gaps[chartIndexRef.current % difficulty.gaps.length];
        chartIndexRef.current += 1;
        changed = true;
      }

      const kept: any[] = [];
      for (const note of notesRef.current) {
        if (now - note.judgeAt > MISS_MS) {
          registerMiss(note);
          changed = true;
        } else {
          kept.push(note);
        }
      }
      notesRef.current = kept;

      if (changed) setNotes([...notesRef.current]);
      setGameTime(now);
      if (phaseRef.current === 'playing') raf = requestAnimationFrame(loop);
    };

    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [phase]);

  return (
    <div className="relative h-screen w-full overflow-hidden bg-slate-950 text-white">
      <style>{`
        @keyframes judgePop {
          0% { opacity: 0; transform: translateY(18px) scale(0.72); }
          18% { opacity: 1; transform: translateY(0) scale(1.08); }
          70% { opacity: 1; transform: translateY(-5px) scale(1); }
          100% { opacity: 0; transform: translateY(-24px) scale(0.94); }
        }
        @keyframes scanFall {
          from { transform: translateY(-120px); opacity: 0; }
          20% { opacity: 0.55; }
          to { transform: translateY(100vh); opacity: 0; }
        }
      `}</style>

      <div className="absolute inset-0" style={{ background: 'linear-gradient(180deg,#07111f 0%,#0f172a 48%,#111827 100%)' }} />
      <div className="absolute inset-0 opacity-45" style={{ backgroundImage: 'linear-gradient(rgba(255,255,255,0.045) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.035) 1px, transparent 1px)', backgroundSize: '42px 42px' }} />
      <div className="absolute left-0 right-0 top-0 h-28 bg-gradient-to-b from-cyan-400/14 to-transparent" />
      <div className="absolute left-[18%] top-[-120px] h-28 w-[2px] bg-cyan-200/35" style={{ animation: 'scanFall 2.8s linear infinite' }} />
      <div className="absolute left-[61%] top-[-120px] h-28 w-[2px] bg-amber-200/35" style={{ animation: 'scanFall 3.4s linear 0.7s infinite' }} />

      <ScoreHud hud={hud} />

      <div className="absolute left-1/2 top-0 h-full w-[min(92vw,920px)] -translate-x-1/2">
        {LANES.map((lane) => (
          <div
            key={lane.id}
            className="absolute top-28 bottom-28 w-px -translate-x-1/2"
            style={{
              left: `${lane.x}%`,
              background: `linear-gradient(180deg, transparent, ${lane.color}44 18%, ${lane.color}22 82%, transparent)`,
              boxShadow: `0 0 18px ${lane.color}55`,
            }}
          />
        ))}

        <div
          className="absolute left-0 right-0 z-0 h-px"
          style={{
            top: `${TARGET_Y}%`,
            background: 'linear-gradient(90deg, transparent, rgba(255,255,255,0.95), transparent)',
            boxShadow: '0 0 28px rgba(255,255,255,0.8), 0 0 54px rgba(34,211,238,0.55)',
          }}
        />
        <div
          className="absolute left-0 right-0 z-0 -translate-y-1/2"
          style={{
            top: `${TARGET_Y}%`,
            height: 'clamp(52px, 8vw, 78px)',
            background: 'linear-gradient(180deg, transparent, rgba(255,255,255,0.07), transparent)',
          }}
        />

        {notes.map((note) => (
          <FallingNote key={note.id} note={note} gameTime={gameTime} />
        ))}

        {LANES.map((lane) => (
          <TargetPad key={lane.id} lane={lane} active={laneFlash[lane.id]} onInput={queueInput} />
        ))}
      </div>

      <JudgmentBurst judgment={judgment} />
      <HardwareStatus inputView={inputView} />

      {phase === 'ready' && <ReadyOverlay onStart={startGame} />}
      {phase === 'gameOver' && <GameOverOverlay hud={hud} onStart={startGame} />}
    </div>
  );
}

export default App;
